  KEY `fk_loans_disbursed_by` (`disbursed_by`),
  KEY `idx_loans_application` (`application_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
',
    'loan_installments' => 'CREATE TABLE `loan_installments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `loan_id` int(10) unsigned NOT NULL,
  `installment_no` int(10) unsigned NOT NULL,
  `period_type` enum(\'monthly\',\'weekly\') NOT NULL DEFAULT \'monthly\',
  `payment_type` enum(\'interest_only\',\'principal_interest\',\'standard\') NOT NULL DEFAULT \'standard\',
  `principal_due` decimal(15,2) NOT NULL DEFAULT 0.00,
  `interest_due` decimal(15,2) NOT NULL DEFAULT 0.00,
  `principal_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `interest_paid_amt` decimal(15,2) NOT NULL DEFAULT 0.00,
  `balance_after` decimal(15,2) NOT NULL DEFAULT 0.00,
  `due_date` date NOT NULL,
  `month_covered` varchar(20) DEFAULT NULL COMMENT \'e.g. Aug 2026\',
  `amount_due` decimal(15,2) NOT NULL DEFAULT 0.00,
  `amount_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `remaining` decimal(15,2) NOT NULL DEFAULT 0.00,
  `status` enum(\'pending\',\'paid\',\'partial\',\'missed\',\'overdue\') NOT NULL DEFAULT \'pending\',
  `paid_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `frequency` enum(\'weekly\',\'monthly\',\'custom\') DEFAULT \'monthly\' COMMENT \'Payment frequency for this installment\',
  `week_number` int(10) unsigned DEFAULT NULL COMMENT \'Week number for weekly installments\',
  `installment_type` enum(\'interest\',\'principal\',\'both\',\'savings\') DEFAULT \'both\' COMMENT \'What this installment covers\',
  `is_grace_period` tinyint(1) NOT NULL DEFAULT 0 COMMENT \'Set when this installment falls inside the loan\'\'s configured grace period (principal deferred, interest still due)\',
  PRIMARY KEY (`id`),
  KEY `idx_inst_loan` (`loan_id`),
  KEY `idx_inst_due` (`due_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
',
    'loan_repayments' => 'CREATE TABLE `loan_repayments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `repayment_number` varchar(20) NOT NULL COMMENT \'PAY-000001\',
  `payment_type` enum(\'installment\',\'interest\',\'weekly_savings\',\'principal\',\'settlement\') NOT NULL DEFAULT \'installment\',
  `loan_type_id` int(10) unsigned DEFAULT NULL,
  `loan_id` int(10) unsigned NOT NULL,
  `member_id` int(10) unsigned NOT NULL,
  `payment_date` date NOT NULL,
  `amount_paid` decimal(15,2) NOT NULL,
  `principal_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `interest_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `savings_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `penalty_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `week_covered` varchar(30) DEFAULT NULL,
  `balance_before` decimal(15,2) NOT NULL,
  `balance_after` decimal(15,2) NOT NULL,
  `payment_method` enum(\'Cash\',\'Airtel Money\',\'MTN Mobile Money\',\'Bank Transfer\',\'Cheque\',\'Other\') NOT NULL DEFAULT \'Cash\',
  `reference_number` varchar(100) DEFAULT NULL,
  `cash_reference_number` varchar(20) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `received_by` int(10) unsigned DEFAULT NULL,
  `journal_entry_id` int(10) unsigned DEFAULT NULL,
  `submission_token` varchar(40) DEFAULT NULL COMMENT \'Server-generated per-form-render idempotency key.\',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `repayment_number` (`repayment_number`),
  UNIQUE KEY `uq_repayments_cash_reference` (`cash_reference_number`),
  UNIQUE KEY `uk_repayments_submission_token` (`submission_token`),
  KEY `fk_repay_user` (`received_by`),
  KEY `idx_repay_loan` (`loan_id`),
  KEY `idx_repay_member` (`member_id`),
  KEY `idx_repay_date` (`payment_date`),
  KEY `idx_repayment_type_loan` (`loan_id`,`payment_type`,`payment_date`),
  KEY `fk_repayments_journal_entry` (`journal_entry_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
',
    'loan_penalties' => 'CREATE TABLE `loan_penalties` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `loan_id` int(10) unsigned NOT NULL,
  `installment_id` bigint(20) unsigned DEFAULT NULL,
  `member_id` int(10) unsigned NOT NULL,
  `days_overdue` int(10) unsigned NOT NULL DEFAULT 0,
  `base_amount` decimal(15,2) NOT NULL COMMENT \'Installment amount penalty is calculated on\',
  `penalty_rate` decimal(5,4) NOT NULL DEFAULT 0.2500,
  `penalty_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `amount_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `status` enum(\'accruing\',\'paid\',\'waived\') NOT NULL DEFAULT \'accruing\',
  `calculated_date` date NOT NULL,
  `paid_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_lp_loan` (`loan_id`),
  KEY `idx_lp_member` (`member_id`),
  KEY `idx_lp_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
',
    'loan_weekly_interest' => 'CREATE TABLE `loan_weekly_interest` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `loan_id` int(10) unsigned NOT NULL,
  `member_id` int(10) unsigned NOT NULL,
  `week_number` int(10) unsigned NOT NULL COMMENT \'Sequential week number from loan start (1, 2, 3...)\',
  `month_number` int(10) unsigned NOT NULL COMMENT \'Which month this week belongs to (1-6)\',
  `week_in_month` tinyint(3) unsigned NOT NULL COMMENT \'Week within month (1-4)\',
  `week_start_date` date NOT NULL,
  `week_end_date` date NOT NULL,
  `interest_due` decimal(15,2) NOT NULL DEFAULT 0.00,
  `interest_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `status` enum(\'pending\',\'paid\',\'partial\',\'overdue\') NOT NULL DEFAULT \'pending\',
  `due_date` date NOT NULL COMMENT \'Last day of the week\',
  `paid_date` date DEFAULT NULL COMMENT \'When fully paid\',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_lwi_loan` (`loan_id`),
  KEY `idx_lwi_member` (`member_id`),
  KEY `idx_lwi_status` (`status`),
  KEY `idx_lwi_week` (`loan_id`,`week_number`),
  KEY `idx_lwi_unpaid` (`loan_id`,`status`,`week_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT=\'Weekly interest tracking for Business Loans with weekly frequency\';
',
    'loan_weekly_savings' => 'CREATE TABLE `loan_weekly_savings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
