    'member_savings_accounts' => 'CREATE TABLE `member_savings_accounts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `account_number` varchar(20) NOT NULL,
  `account_type` enum(\'compulsory\',\'voluntary\',\'joint\',\'corporate\',\'fixed_deposit\') NOT NULL,
  `ownership_type` enum(\'individual\',\'joint\',\'corporate\') NOT NULL,
  `principal_amount` decimal(15,2) DEFAULT NULL COMMENT \'Fixed Deposit only: the original lump-sum principal. NULL for every other account type.\',
  `deposit_date` date DEFAULT NULL COMMENT \'Fixed Deposit only: the date the lump sum was deposited.\',
  `term_months` int(10) unsigned DEFAULT NULL COMMENT \'Fixed Deposit only: the agreed term in months (3/6/12/18/24 today; the set is a PHP-side allow-list, not a DB constraint, so more can be added later without a migration).\',
  `maturity_date` date DEFAULT NULL COMMENT \'Fixed Deposit only: deposit_date + term_months, calculated and stored once at opening.\',
  `interest_rate` decimal(10,6) DEFAULT NULL COMMENT \'Fixed Deposit only: the agreed ANNUAL rate (%), locked at opening. Same precision as loans.interest_rate for consistency. Changing the default rate setting never alters an existing account\'\'s stored rate.\',
  `expected_interest` decimal(15,2) DEFAULT NULL COMMENT \'Fixed Deposit only: principal x rate x (term_months/12), simple interest, computed once at opening.\',
  `expected_maturity_amount` decimal(15,2) DEFAULT NULL COMMENT \'Fixed Deposit only: principal_amount + expected_interest.\',
  `status` enum(\'active\',\'dormant\',\'closed\',\'matured\') NOT NULL DEFAULT \'active\',
  `opened_date` date NOT NULL,
  `closed_date` date DEFAULT NULL,
  `qualification_met_date` date DEFAULT NULL COMMENT \'Compulsory only: date the 2-deposit/40,000 threshold was first reached. Permanent once set -- never cleared.\',
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_account_number` (`account_number`),
  KEY `idx_account_type` (`account_type`),
  KEY `idx_account_status` (`status`),
  KEY `fk_msa_created_by` (`created_by`)
) ENGINE=InnoDB AUTO_INCREMENT=126 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
',
    'savings' => 'CREATE TABLE `savings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `member_id` int(10) unsigned NOT NULL,
  `savings_account_id` int(10) unsigned DEFAULT NULL,
  `receipt_number` varchar(20) NOT NULL,
  `transaction_type` enum(\'opening_balance\',\'deposit\',\'withdrawal\',\'adjustment\') NOT NULL DEFAULT \'deposit\',
  `debit` decimal(15,2) DEFAULT NULL,
  `credit` decimal(15,2) DEFAULT NULL,
  `running_balance` decimal(15,2) NOT NULL DEFAULT 0.00,
  `description` varchar(255) DEFAULT NULL,
  `amount_legacy` decimal(15,2) DEFAULT NULL,
  `payment_method` enum(\'Cash\',\'Airtel Money\',\'MTN Mobile Money\',\'Bank Transfer\',\'Cheque\',\'Other\') NOT NULL DEFAULT \'Cash\',
  `reference_number` varchar(100) DEFAULT NULL,
  `cash_reference_number` varchar(20) DEFAULT NULL,
  `transaction_date` date NOT NULL,
  `is_fixed_deposit_principal` tinyint(1) DEFAULT NULL COMMENT \'Set to 1 only on a Fixed Deposit account\'\'s one allowed opening-deposit row. NULL for every other transaction.\',
  `financial_year` year(4) NOT NULL,
  `notes` text DEFAULT NULL,
  `recorded_by` int(10) unsigned DEFAULT NULL,
  `authorized_by` int(10) unsigned DEFAULT NULL,
  `journal_entry_id` int(10) unsigned DEFAULT NULL,
  `bf_posting_mode` enum(\'verified_asset\',\'historical_only\') DEFAULT NULL COMMENT \'Only meaningful when transaction_type=opening_balance. NULL for every other row and for pre-existing B/F rows not yet classified.\',
  `bf_asset_account_id` int(10) unsigned DEFAULT NULL COMMENT \'Only set when bf_posting_mode=verified_asset -- the accounts.id actually debited.\',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `receipt_number` (`receipt_number`),
  UNIQUE KEY `uq_fixed_deposit_principal` (`savings_account_id`,`is_fixed_deposit_principal`),
  UNIQUE KEY `uq_savings_cash_reference` (`cash_reference_number`),
  KEY `fk_savings_recorded_by` (`recorded_by`),
  KEY `idx_savings_member` (`member_id`),
  KEY `idx_savings_date` (`transaction_date`),
  KEY `idx_savings_year` (`financial_year`),
  KEY `fk_savings_authorized_by` (`authorized_by`),
  KEY `idx_savings_member_date` (`member_id`,`transaction_date`,`id`),
  KEY `fk_savings_journal_entry` (`journal_entry_id`),
  KEY `fk_savings_bf_asset_account` (`bf_asset_account_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
',
    'activity_logs' => 'CREATE TABLE `activity_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned DEFAULT NULL,
