) ENGINE=InnoDB AUTO_INCREMENT=322 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
',
    'notifications' => 'CREATE TABLE `notifications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `type` enum(\'info\',\'success\',\'warning\',\'critical\') NOT NULL DEFAULT \'info\',
  `priority` enum(\'low\',\'normal\',\'high\') NOT NULL DEFAULT \'normal\',
  `reference_type` varchar(50) DEFAULT NULL COMMENT \'loan, savings, withdrawal, system, user\',
  `reference_id` int(10) unsigned DEFAULT NULL,
  `user_id` int(10) unsigned DEFAULT NULL COMMENT \'Target user (NULL = all admins)\',
  `recipient_role` varchar(50) DEFAULT NULL COMMENT \'Audit metadata: the role this row was resolved from at creation time, if any. Never used to re-resolve visibility at read time.\',
  `member_id` int(10) unsigned DEFAULT NULL,
  `loan_id` int(10) unsigned DEFAULT NULL,
  `savings_account_id` int(10) unsigned DEFAULT NULL,
  `action_url` varchar(255) DEFAULT NULL,
  `event_date` date DEFAULT NULL,
  `unique_event_key` varchar(191) DEFAULT NULL,
  `is_broadcast` tinyint(1) NOT NULL DEFAULT 0,
  `is_read` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `read_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_notification_event_key` (`unique_event_key`),
  KEY `idx_user_read` (`user_id`,`is_read`),
  KEY `idx_type` (`type`),
  KEY `idx_ref` (`reference_type`,`reference_id`),
  KEY `fk_notif_member` (`member_id`),
  KEY `fk_notif_loan` (`loan_id`),
  KEY `fk_notif_savings_account` (`savings_account_id`)
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
',
    'member_fees' => 'CREATE TABLE `member_fees` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
